package org.novasos.healthysv2.pharmacy;
import static org.novasos.healthysv2.pharmacy.api.PharmacyDtos.*;import java.net.*;import java.util.*;import jakarta.validation.Valid;import io.swagger.v3.oas.annotations.tags.Tag;import org.novasos.healthysv2.shared.api.ApiPaths;import org.novasos.healthysv2.shared.api.dto.PageResponse;import org.springframework.data.domain.Pageable;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping(ApiPaths.V1)@Tag(name="Pharmacy",description="Prescriptions, dispensing and medication stock")@PreAuthorize("hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','DOCTOR','NURSE','PHARMACIST','PATIENT')")class PharmacyController{
 private static final String PRESCRIBE="hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','DOCTOR')",PHARMACY="hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','PHARMACIST')";private final PharmacyService service;PharmacyController(PharmacyService service){this.service=service;}
 @PostMapping("/prescriptions")@PreAuthorize(PRESCRIBE)ResponseEntity<PrescriptionResponse>create(@Valid@RequestBody CreatePrescriptionRequest r){var out=service.create(r);return ResponseEntity.created(URI.create(ApiPaths.V1+"/prescriptions/"+out.id())).body(out);}@GetMapping("/prescriptions/{id}")PrescriptionResponse find(@PathVariable UUID id){return service.find(id);}@GetMapping("/prescriptions")@PreAuthorize("hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','DOCTOR','NURSE','PHARMACIST')")PageResponse<PrescriptionSummary>search(@RequestParam(required=false)UUID patientId,@RequestParam(required=false)UUID organizationId,@RequestParam(required=false)String status,Pageable pageable){return service.search(patientId,organizationId,status,pageable);}@PostMapping("/prescriptions/{id}/cancel")@PreAuthorize(PRESCRIBE)PrescriptionResponse cancel(@PathVariable UUID id){return service.cancel(id);}@PostMapping("/prescriptions/{id}/dispenses")@PreAuthorize(PHARMACY)ResponseEntity<DispenseResponse>dispense(@PathVariable UUID id,@Valid@RequestBody CreateDispenseRequest r){return ResponseEntity.status(201).body(service.dispense(id,r));}
 @PostMapping("/medication-stocks/replenish")@PreAuthorize(PHARMACY)MedicationStockResponse replenish(@Valid@RequestBody ReplenishStockRequest r){return service.replenish(r);}@GetMapping("/medication-stocks")@PreAuthorize(PHARMACY)List<MedicationStockResponse>stock(@RequestParam(required=false)UUID organizationId,@RequestParam(required=false)UUID medicationCatalogId){return service.stock(organizationId,medicationCatalogId);}@GetMapping("/medication-catalog")List<MedicationCatalogResponse>catalog(@RequestParam(required=false)String query){return service.catalog(query);}
}
